sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_StartInterview(vBusinessProcess,vUser,vExpected)
	{
		function TestCase_StartInterview_CheckResult(vInput,vExpected,vResult)
		{
			if (vExpected == false)
			{
				return (vExpected == vResult);
			}
			return x_snc_devtools.IsValidSysId(vResult);
		}
		
		test.TestCase(
			'Function StartInterview()',
			StartInterview,
			{
				'vBusinessProcess': vBusinessProcess,
				'vUser': vUser
			},
			vExpected,
			TestCase_StartInterview_CheckResult);
	}
		
	TestCase_StartInterview(null,null,false);

	var grBP = new GlideRecord('x_snc_agenticbpc_business_process');
	grBP.initialize();
	grBP.name = 'TEST1';
	var strBusinessProcessSysId = grBP.insert();

	TestCase_StartInterview(strBusinessProcessSysId,null,false);

	var strUserSysId = x_snc_devtools.CreateTestUser('ATF Agentic BPC Stakeholder 1');

	var grStakeholder = new GlideRecord('x_snc_agenticbpc_stakeholder');
	grStakeholder.initialize();
	grStakeholder.user = strUserSysId;
	grStakeholder.business_process = strBusinessProcessSysId;
	var strStakeholderSysId = grStakeholder.insert();

	TestCase_StartInterview(strBusinessProcessSysId,strUserSysId,false);

	x_snc_devtools.UserAddRole(strUserSysId,'x_snc_agenticbpc.stakeholder');

	TestCase_StartInterview(strBusinessProcessSysId,strUserSysId,true);

	
	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
